/**
 * What a country sets (PRODUCT-REVIEW R76): its currency, the first day of its week and its
 * weekend (kept apart from the work week, which is derived from them), whether its clock counts
 * to 12, the Arabic spoken there, and the ways people are paid there. One module, read by the
 * server for a person's and an organization's derived facts (`MeView`, `OrgView`) and by
 * whatever else needs a country's own default; the data is CLDR's (`countries-data.ts`,
 * generated by scripts/geo.mjs, deviations only), the curated parts are here. Pure, no zod.
 */
import type { ArabicVariety } from './arabic-variety';
import { COUNTRY_DATA, WORLD } from './countries-data';
import { msg } from './i18n';
import type { PaymentKind } from './payments';
import { weekOrder } from './time';

/** A way people are paid in a country, offered when a host adds one (R62): its kind and its name. */
export interface PayKindHint {
  kind: PaymentKind;
  /** A brand or a scheme ("InstaPay", "IBAN"): a key, shown through `tr`. */
  label: string;
}

export interface CountryFacts {
  /** ISO 3166-1 alpha-2, or null for someone who said nowhere. */
  code: string | null;
  /** ISO 4217, where the country has one of its own (Antarctica doesn't). */
  currency: string | null;
  /** The first day of the calendar week, 0 = Sunday: Saturday in Egypt, Sunday in the US, Monday in France. */
  weekStart: number;
  /** The weekend's days, 0 = Sunday: Friday and Saturday in Egypt, Saturday and Sunday in France. */
  weekend: number[];
  /**
   * The days worked, from the week's first day on: the week less its weekend (Sunday to
   * Thursday in Egypt), unless the country works otherwise (`WORKWEEK_OVERRIDES`).
   */
  workweek: number[];
  /** Whether the clock counts to 12 (Egypt, the US) or to 24 (France, Turkey). */
  hour12: boolean;
  /** The Arabic spoken there, where it's one country's own. */
  variety: ArabicVariety | null;
  /** The ways people are paid there, most common first. */
  payKinds: PayKindHint[];
}

const MON_FRI = [1, 2, 3, 4, 5];

/** Where the weekend's complement isn't the week worked: a half day left out, a single day off. */
const WORKWEEK_OVERRIDES: Readonly<Record<string, readonly number[]>> = {
  // Iran: Friday off, Thursday a half day, so the week worked is Saturday to Wednesday.
  IR: [6, 0, 1, 2, 3],
};
/** Where CLDR has no weekend of the country's own but the country keeps one (R31). */
const WEEKEND_OVERRIDES: Readonly<Record<string, readonly number[]>> = {
  // Nepal: Saturday alone.
  NP: [6],
};

const VARIETIES: Readonly<Record<Exclude<ArabicVariety, 'standard'>, readonly string[]>> = {
  egyptian: ['EG'],
  gulf: ['SA', 'AE', 'KW', 'QA', 'BH', 'OM'],
  levantine: ['LB', 'SY', 'JO', 'PS'],
  iraqi: ['IQ'],
  maghrebi: ['MA', 'DZ', 'TN', 'LY'],
  sudanese: ['SD'],
  yemeni: ['YE'],
};
const VARIETY_OF = new Map<string, ArabicVariety>(
  Object.entries(VARIETIES).flatMap(([variety, codes]) =>
    codes.map((code) => [code, variety as ArabicVariety] as const),
  ),
);

/** The countries whose bank accounts are IBANs: a transfer asks for one, not an account number. */
const IBAN = new Set(
  'AD AE AL AT AZ BA BE BG BH BR BY CH CR CY CZ DE DK DO EE EG ES FI FO FR GB GE GI GL GR GT HR HU IE IL IQ IS IT JO KW KZ LB LC LI LT LU LV LY MC MD ME MK MR MT MU NL NO PK PL PS PT QA RO RS SA SC SE SI SK SM ST SV TL TN TR UA VA VG XK'.split(
    ' ',
  ),
);
const BANK: PayKindHint = { kind: 'bank', label: msg('Bank transfer') };
const IBAN_HINT: PayKindHint = { kind: 'bank', label: msg('IBAN') };
const CASH: PayKindHint = { kind: 'cash', label: msg('Cash') };
const wallet = (label: string): PayKindHint => ({ kind: 'wallet', label });
const other = (label: string): PayKindHint => ({ kind: 'other', label });
/** The ways people are paid in a country, by name (brands as they're written), most common first. */
const PAY_KINDS: Readonly<Record<string, readonly PayKindHint[]>> = {
  EG: [wallet(msg('InstaPay')), wallet(msg('Vodafone Cash')), other(msg('Fawry')), IBAN_HINT, CASH],
  SA: [wallet(msg('STC Pay')), IBAN_HINT, CASH],
  AE: [IBAN_HINT, CASH],
  JO: [wallet(msg('CliQ')), IBAN_HINT, CASH],
  LB: [wallet(msg('Whish')), other(msg('OMT')), BANK, CASH],
  MA: [other(msg('CashPlus')), BANK, CASH],
  TR: [IBAN_HINT, CASH],
  US: [wallet(msg('Zelle')), wallet(msg('Venmo')), BANK, CASH],
  GB: [BANK, CASH],
  IN: [wallet(msg('UPI')), BANK, CASH],
  PK: [wallet(msg('JazzCash')), wallet(msg('Easypaisa')), IBAN_HINT, CASH],
  KE: [wallet(msg('M-Pesa')), BANK, CASH],
};

/** What a country sets, with the world's defaults where it says nothing; the defaults alone for none. */
export function countryFacts(country: string | null | undefined): CountryFacts {
  const code = country ? country.toUpperCase() : null;
  const d = code ? COUNTRY_DATA[code] : undefined;
  const weekStart = d?.f ?? WORLD.firstDay;
  const weekend = [...((code ? WEEKEND_OVERRIDES[code] : undefined) ?? d?.w ?? WORLD.weekend)];
  const override = code ? WORKWEEK_OVERRIDES[code] : undefined;
  const workweek = override
    ? [...override]
    : code
      ? weekOrder(weekStart).filter((day) => !weekend.includes(day))
      : [...MON_FRI];
  return {
    code,
    currency: d?.c ?? null,
    weekStart,
    weekend,
    workweek,
    hour12: d?.h === 1 || (!d && WORLD.hour12),
    variety: code ? (VARIETY_OF.get(code) ?? null) : null,
    payKinds: [
      ...((code ? PAY_KINDS[code] : undefined) ??
        (code && IBAN.has(code) ? [IBAN_HINT, CASH] : [BANK, CASH])),
    ],
  };
}

/** A country's currency (ISO 4217), when it has one of its own. */
export function currencyOfCountry(country: string | null | undefined): string | null {
  return countryFacts(country).currency;
}

/**
 * The days worked where someone lives (R31): Sunday to Thursday in Egypt, Monday to Friday
 * here; Monday to Friday for nowhere in particular.
 */
export function defaultWorkweek(country: string | null | undefined): number[] {
  return countryFacts(country).workweek;
}

/** The Arabic spoken where someone lives, or null where it isn't one country's own. */
export function varietyOfCountry(country: string | null | undefined): ArabicVariety | null {
  return countryFacts(country).variety;
}
